use crate::i18n::use_i18n;
use serde::{Deserialize, Serialize};
use yew::prelude::*;

#[derive(Debug, Serialize, Deserialize)]
struct License {
    expression: String,
}

#[derive(Debug, Serialize, Deserialize)]
struct Component {
    name: String,
    version: String,
    #[serde(default)]
    licenses: Option<Vec<License>>,
}

#[derive(Debug, Serialize, Deserialize)]
struct CycloneDX {
    #[serde(default)]
    components: Vec<Component>,
}

#[derive(Properties, PartialEq, Default)]
pub struct AppDependenciesProps {
    /// CycloneDX JSON generated by the host application.
    #[prop_or_default]
    pub sbom_json: Option<AttrValue>,
}

#[function_component(AppDependenciesComponent)]
pub fn app_dependencies(props: &AppDependenciesProps) -> Html {
    let i18n = use_i18n();
    let sbom = use_memo(props.sbom_json.clone(), |provided| {
        let json = provided
            .as_ref()
            .map(|json| json.as_str())
            .unwrap_or(env!("CARGO_SBOM"));
        serde_json::from_str::<CycloneDX>(json).unwrap_or_else(|error| {
            tracing::warn!("Failed to parse dependency inventory: {error}");
            CycloneDX { components: vec![] }
        })
    });

    let filter = use_state(String::new);
    let show_list = use_state(|| false);

    let mut license_count = std::collections::BTreeMap::new();
    for component in &sbom.components {
        for license in component.licenses.iter().flatten() {
            *license_count.entry(&license.expression).or_insert(0) += 1;
        }
    }

    let filtered_components = sbom
        .components
        .iter()
        .filter(|component| {
            component
                .name
                .to_lowercase()
                .contains(&filter.to_lowercase())
        })
        .collect::<Vec<_>>();

    let onfilter = {
        let filter = filter.clone();
        Callback::from(move |e: Event| {
            #[cfg(feature = "csr")]
            {
                let input: web_sys::HtmlInputElement = e.target_unchecked_into();
                filter.set(input.value());
            }
        })
    };

    let toggle_list = {
        let show_list = show_list.clone();
        Callback::from(move |_| {
            show_list.set(!*show_list);
        })
    };

    html! {
        <div class="app-dependencies">
            <div class="app-dependencies__summary">
                <div class="app-dependencies__header">
                    <span class="app-dependencies__count">
                        {format!("{} {}", sbom.components.len(), i18n.t("Dependencies"))}
                    </span>
                    <button class="app-dependencies__toggle" onclick={toggle_list}>
                        {if *show_list { i18n.t("Hide List") } else { i18n.t("Show List") }}
                    </button>
                </div>
                <div class="app-dependencies__licenses">
                    {for license_count.iter().map(|(license, count)| {
                        html! {
                            <span class="license-badge" >
                                {format!("{} ({})", license, count)}
                            </span>
                        }
                    })}
                </div>
            </div>
            if *show_list {
                <div class="app-dependencies__list-container">
                    <input
                        type="text"
                        class="app-dependencies__search"
                        aria-label={i18n.t("Search dependencies...")}
                        placeholder={i18n.t("Search dependencies...")}
                        onchange={onfilter}
                    />
                    <div class="app-dependencies__list">
                        {for filtered_components.iter().map(|component| {
                            html! {
                                <div class="app-dependencies__item">
                                    <span class="app-dependencies__name">
                                        {&component.name} {" "} {&component.version}
                                    </span>
                                    <span class="app-dependencies__item-licenses">
                                        {if let Some(licenses) = &component.licenses {
                                            html! { <>{for licenses.iter().map(|license| html! {
                                                <span class="license-badge license-badge--small">{&license.expression}</span>
                                            })}</> }
                                        } else {
                                            html! { <span class="license-badge license-badge--small">{i18n.t("Unknown")}</span> }
                                        }}
                                    </span>
                                </div>
                            }
                        })}
                    </div>
                </div>
            }
        </div>
    }
}

#[cfg(feature = "yew-preview")]
mod preview {
    use super::*;
    use yew_preview::prelude::*;

    yew_preview::create_preview!(AppDependenciesComponent, AppDependenciesProps {
        sbom_json: Some(r#"{"components":[{"name":"example","version":"1.0.0","licenses":[{"expression":"MIT OR Apache-2.0"}]}]}"#.into()),
    },);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_host_inventory_with_optional_licenses() {
        let inventory: CycloneDX = serde_json::from_str(
            r#"{"components":[{"name":"example","version":"1.0","licenses":[{"expression":"MIT OR Apache-2.0"}]},{"name":"private","version":"2.0"}]}"#,
        ).unwrap();
        assert_eq!(inventory.components.len(), 2);
        assert_eq!(
            inventory.components[0].licenses.as_ref().unwrap()[0].expression,
            "MIT OR Apache-2.0"
        );
        assert!(inventory.components[1].licenses.is_none());
    }

    #[test]
    fn accepts_disabled_sbom_fallback() {
        let inventory: CycloneDX = serde_json::from_str("{}").unwrap();
        assert!(inventory.components.is_empty());
    }
}
